/**
 * Flat FFI error for the agent surface. `AgentError` is `#[non_exhaustive]`
 * upstream, so unknown future variants land in `Other`.
 */
public 
enum AgentError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Busy(String
    )
    case EmptyContext
    case ContinueFromAssistant
    case NoDefaultStreamFn
    case Other(String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AgentError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAgentError: FfiConverterRustBuffer {
    typealias SwiftType = AgentError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AgentError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Busy(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .EmptyContext
        case 3: return .ContinueFromAssistant
        case 4: return .NoDefaultStreamFn
        case 5: return .Other(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AgentError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Busy(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .EmptyContext:
            writeInt(&buf, Int32(2))
        
        
        case .ContinueFromAssistant:
            writeInt(&buf, Int32(3))
        
        
        case .NoDefaultStreamFn:
            writeInt(&buf, Int32(4))
        
        
        case let .Other(v1):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
}


