/**
 * One agent-loop event. Awaited sequentially per event by the sink
 * (see `AgentEventSink`): the loop does not advance until `emit` resolves.
 */

public enum AgentEvent: Equatable, Hashable {
    
    case agentStart
    case agentEnd(messages: [AgentMessage]
    )
    case turnStart
    case turnEnd(message: AgentMessage, toolResults: [ToolResultMessage]
    )
    case messageStart(message: AgentMessage
    )
    case messageUpdate(message: AgentMessage, assistantMessageEvent: AssistantMessageEvent
    )
    case messageEnd(message: AgentMessage
    )
    case toolExecutionStart(toolCallId: String, toolName: String, argsJson: String
    )
    case toolExecutionUpdate(toolCallId: String, toolName: String, argsJson: String, partialResult: AgentToolResult
    )
    case toolExecutionEnd(toolCallId: String, toolName: String, result: AgentToolResult, isError: Bool
    )





}

#if compiler(>=6)
extension AgentEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAgentEvent: FfiConverterRustBuffer {
    typealias SwiftType = AgentEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AgentEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .agentStart
        
        case 2: return .agentEnd(messages: try FfiConverterSequenceTypeAgentMessage.read(from: &buf)
        )
        
        case 3: return .turnStart
        
        case 4: return .turnEnd(message: try FfiConverterTypeAgentMessage.read(from: &buf), toolResults: try FfiConverterSequenceTypeToolResultMessage.read(from: &buf)
        )
        
        case 5: return .messageStart(message: try FfiConverterTypeAgentMessage.read(from: &buf)
        )
        
        case 6: return .messageUpdate(message: try FfiConverterTypeAgentMessage.read(from: &buf), assistantMessageEvent: try FfiConverterTypeAssistantMessageEvent.read(from: &buf)
        )
        
        case 7: return .messageEnd(message: try FfiConverterTypeAgentMessage.read(from: &buf)
        )
        
        case 8: return .toolExecutionStart(toolCallId: try FfiConverterString.read(from: &buf), toolName: try FfiConverterString.read(from: &buf), argsJson: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .toolExecutionUpdate(toolCallId: try FfiConverterString.read(from: &buf), toolName: try FfiConverterString.read(from: &buf), argsJson: try FfiConverterString.read(from: &buf), partialResult: try FfiConverterTypeAgentToolResult.read(from: &buf)
        )
        
        case 10: return .toolExecutionEnd(toolCallId: try FfiConverterString.read(from: &buf), toolName: try FfiConverterString.read(from: &buf), result: try FfiConverterTypeAgentToolResult.read(from: &buf), isError: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AgentEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .agentStart:
            writeInt(&buf, Int32(1))
        
        
        case let .agentEnd(messages):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceTypeAgentMessage.write(messages, into: &buf)
            
        
        case .turnStart:
            writeInt(&buf, Int32(3))
        
        
        case let .turnEnd(message,toolResults):
            writeInt(&buf, Int32(4))
            FfiConverterTypeAgentMessage.write(message, into: &buf)
            FfiConverterSequenceTypeToolResultMessage.write(toolResults, into: &buf)
            
        
        case let .messageStart(message):
            writeInt(&buf, Int32(5))
            FfiConverterTypeAgentMessage.write(message, into: &buf)
            
        
        case let .messageUpdate(message,assistantMessageEvent):
            writeInt(&buf, Int32(6))
            FfiConverterTypeAgentMessage.write(message, into: &buf)
            FfiConverterTypeAssistantMessageEvent.write(assistantMessageEvent, into: &buf)
            
        
        case let .messageEnd(message):
            writeInt(&buf, Int32(7))
            FfiConverterTypeAgentMessage.write(message, into: &buf)
            
        
        case let .toolExecutionStart(toolCallId,toolName,argsJson):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(toolCallId, into: &buf)
            FfiConverterString.write(toolName, into: &buf)
            FfiConverterString.write(argsJson, into: &buf)
            
        
        case let .toolExecutionUpdate(toolCallId,toolName,argsJson,partialResult):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(toolCallId, into: &buf)
            FfiConverterString.write(toolName, into: &buf)
            FfiConverterString.write(argsJson, into: &buf)
            FfiConverterTypeAgentToolResult.write(partialResult, into: &buf)
            
        
        case let .toolExecutionEnd(toolCallId,toolName,result,isError):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(toolCallId, into: &buf)
            FfiConverterString.write(toolName, into: &buf)
            FfiConverterTypeAgentToolResult.write(result, into: &buf)
            FfiConverterBool.write(isError, into: &buf)
            
        }
    }
}


