/**
 * Provider-level streaming event; each variant carries the full accumulated
 * `partial` message (self-synchronizing — no delta stitching in the host).
 */

public enum AssistantMessageEvent: Equatable, Hashable {
    
    case start(partial: AssistantMessage
    )
    case textStart(contentIndex: UInt32, partial: AssistantMessage
    )
    case textDelta(contentIndex: UInt32, delta: String, partial: AssistantMessage
    )
    case textEnd(contentIndex: UInt32, content: String, partial: AssistantMessage
    )
    case thinkingStart(contentIndex: UInt32, partial: AssistantMessage
    )
    case thinkingDelta(contentIndex: UInt32, delta: String, partial: AssistantMessage
    )
    case thinkingEnd(contentIndex: UInt32, thinking: String, partial: AssistantMessage
    )
    case toolCallStart(contentIndex: UInt32, partial: AssistantMessage
    )
    case toolCallDelta(contentIndex: UInt32, delta: String, partial: AssistantMessage
    )
    case toolCallEnd(contentIndex: UInt32, toolCall: AgentToolCall, partial: AssistantMessage
    )
    case done(reason: StopReason, message: AssistantMessage
    )
    case error(reason: StopReason, error: AssistantMessage
    )





}

