    typealias SwiftType = AssistantMessageEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AssistantMessageEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .start(partial: try FfiConverterTypeAssistantMessage.read(from: &buf)
        )
        
        case 2: return .textStart(contentIndex: try FfiConverterUInt32.read(from: &buf), partial: try FfiConverterTypeAssistantMessage.read(from: &buf)
        )
        
        case 3: return .textDelta(contentIndex: try FfiConverterUInt32.read(from: &buf), delta: try FfiConverterString.read(from: &buf), partial: try FfiConverterTypeAssistantMessage.read(from: &buf)
        )
        
        case 4: return .textEnd(contentIndex: try FfiConverterUInt32.read(from: &buf), content: try FfiConverterString.read(from: &buf), partial: try FfiConverterTypeAssistantMessage.read(from: &buf)
        )
        
        case 5: return .thinkingStart(contentIndex: try FfiConverterUInt32.read(from: &buf), partial: try FfiConverterTypeAssistantMessage.read(from: &buf)
        )
        
        case 6: return .thinkingDelta(contentIndex: try FfiConverterUInt32.read(from: &buf), delta: try FfiConverterString.read(from: &buf), partial: try FfiConverterTypeAssistantMessage.read(from: &buf)
        )
        
        case 7: return .thinkingEnd(contentIndex: try FfiConverterUInt32.read(from: &buf), thinking: try FfiConverterString.read(from: &buf), partial: try FfiConverterTypeAssistantMessage.read(from: &buf)
        )
        
